/** 
 * {@inheritDoc}<p>This method returns a serializable  {@code ImmutableSortedSet}. <p>The  {@link SortedSet#tailSet} documentation states that a subset of asubset throws an  {@link IllegalArgumentException} if passed a{@code fromElement} smaller than an earlier {@code fromElement}. However, this method doesn't throw an exception in that situation, but instead keeps the original  {@code fromElement}.
 */
@Override public ImmutableSortedSet<E> tailSet(E fromElement){
  try {
    return tailSetImpl(checkNotNull(fromElement));
  } catch (NullPointerException e) {
    throw new IllegalArgumentException("fromElement cannot be null", e);
  }
}
